def count(n):
    if n == 0:
        return 0
    return 2 * count(n - 1) + 1

def hanoi(n, src, dst, via, moves):
    if n == 0:
        return
    hanoi(n - 1, src, via, dst, moves)
    moves.append(src + " -> " + dst)
    hanoi(n - 1, via, dst, src, moves)

n = int(input())
print(count(n))
if n <= 4:
    moves = []
    hanoi(n, "A", "C", "B", moves)
    for move in moves:
        print(move)
